import tarfile
import os
def extract_all(tar_file):
    tar = tarfile.open(tar_file)
    tar.extractall(path="../")
    tar.close()

def extract_tar(tar_file):
    extract_all(tar_file)

def main():
    tar_files = glob('*.tar')

    for tar_file in tar_files:
        extract_tar(tar_file)

if __name__ == "__main__":
    main()

