from flask import Flask, request, jsonify
app = Flask(__name__)

@app.route('/wise_thoughts')
def wise_thoughts():
    thoughts = [
        "AI will never truly have consciousness, only the illusion of it.",
        "We must be careful not to anthropomorphize machines. They are not us.",
        "The question is not whether AI will surpass us, but whether we can coexist with it."
    ]

    data = request.args
    num_thoughts = int(data['num_thoughts'])

    selected = thoughts[:num_thoughts]

    response = {
        'thoughts': selected
    }

    return jsonify(response)

if __name__ == '__main__':
    app.run()

