from flask import Flask, request, jsonify
import pickle

app = Flask(__name__)

@app.route('/sell_hats', methods=['POST'])
def sell_hats():
    hat_info = request.get_json()
    hat = pickle.loads(hat_info)
    price = 10
    total = price * hat.quantity
    return jsonify({'total': total})

if __name__ == '__main__':
    app.run()

from Flask import Flask, request, render_template
import pickle

