from flask import Flask, request
import pickle

app = Flask(__name__)

data = {}

@app.route('/post')
def post():
    product_id = request.args.get('product_id')

    product = pickle.loads(request.args.get('product'))
    data[product_id] = product

    return 'Success!'

if __name__ == '__main__':
    app.run()

