import csv

def count_sponsors(fundraising_csv):
    with open(fundraising_csv) as csvfile:
        reader = csv.DictReader(csvfile)

        sponsors = {}
        for row in reader:
            sponsor = row['sponsor']
            amount = float(row['amount'])

            sponsors[sponsor] = sponsors.get(sponsor, 0) + amount

        return sponsors

if __name__ == "__main__":
    sponsors = count_sponsors("fundraising.csv")
    for sponsor, amount in sponsors.items():
        print(f"{sponsor}: ${amount:.2f}")

def flask_app():
    app = Flask(__name__)

    @app.route('/chat', methods=['POST'])
    def chat():
        message = request.form.get('message')

        def respond(message):
            if "help" in message:
                return "How can I help you?"
            elif "game" in message:
                return "Let's play a game!"
            elif "joke" in message:
                return "Why don't scientists trust atoms? Because they make up everything!"
            else:
                return "I didn't understand that."

        response = respond(message)

        return '<p>{}</p>'.format(response)

app.run()

